"""Stages the transport kit (families A, B, C) into a checkout of the PRIVATE asset repository (ARO-CONTENT) as new versions (v001) of 52 new ids, in the layout its README and validator define; the file formats and
rules are those of kano_kit.stage_private and env_kit.stage_e4 (append-only: an existing file is never overwritten with other bytes; the registry status written is `blender_validation_passed` and nothing is marked
imported, reviewed or approved). What it adds to the checkout:
  blender/projects/<kind>/<id>/v001/ (.blend, project.json)   blender/validation/<id>/v001.json   blender/export_manifests/<id>/v001/<id>.manifest.json
  unity/Models/<id>/v001/ (.fbx, .glb, <id>.manifest.json with the catalogue entry: light heads, text face, tags)   unity/Textures/transport_kit/T_*.png (the palette textures; shared kit maps are NOT copied twice)
  unity/Materials/aro_materials.json (merged: the new materials are added, every existing definition must be identical)   previews/<id>/v001/*.jpg   unity/placements/env_*_dry.json (the review scenes)
  LICENSES.md (one row per id)   registry/asset_registry.json (52 new entries, two existing planned entries `aro_bench_a` and `aro_pallet_stack_a` moved to this version)   manifests/transport_kit.release.json (+ the freeze manifest)
**Overlap with the library plan.** The registry already lists planned or built assets that are the same thing under another id (OVERLAP below). Nothing is merged or dropped here: each new entry carries the planned id(s) in
`overlapsPlanned` and an OPEN flag saying the owner decides which id the game uses.
Run from tools/blender:  PYTHONPATH=. ~/.aro/venv/bin/python -m transport_kit.stage_private --content <ARO-CONTENT checkout> --game-docs <game repository docs/kano> --previews <dir of render_tk output>"""
from __future__ import annotations
import argparse, hashlib, json, shutil, sys, time
from pathlib import Path
from aro_blender import workspace as ws

TOOLS = ["Blender 5.2.3 LTS (bpy)", "tools/blender/transport_kit", "numpy (BSD) and Pillow (HPND), used by the generator scripts only"]
LICENCE_EVIDENCE = ("Original geometry and procedural textures generated by code in this project (tools/blender/transport_kit); the design follows the generated concept references {refs} supplied by the owner as private "
                    "design references (not Kano-verified); no photograph, third-party model or third-party texture is used; no brand, plate or logo. The owner confirmed on 2026-11-01 that the generated Blender assets are "
                    "intended for this project, subject to accurate licensing records of any third-party content and tools (listed in thirdParty).")
THIRD_PARTY = ["Blender 5.2.3 (GPL; the models and textures it writes are not encumbered by it)", "numpy (BSD) and Pillow (HPND), used by the generator scripts only"]

# new id -> planned or built registry ids that are the same thing (the library plan of the master plan, not the transport breakdown)
OVERLAP = {
    "rg_ngn_warehouse_hall_a": ["aro_warehouse_steel_large_a"], "aro_dock_leveller_set": ["aro_dock_door_bay_a"], "aro_gate_sliding_a": ["aro_gate_sliding_steel_a", "aro_barrier_arm_gate_a"],
    "aro_fuel_island_truck": ["aro_fuel_canopy_truck_a", "aro_fuel_pump_a"], "aro_truck_trailer_parked_b": ["aro_trailer_box_a"], "aro_yard_mast_light": ["aro_streetlight_pole_tall_yard_a"],
    "aro_bollard_set": ["aro_bollard_yellow_a"], "aro_wall_plot_set": ["aro_wall_perimeter_plain_a"], "kano_bus_terminal_hall_a": ["aro_bus_terminal_hall_a", "kano_bus_terminal_a"],
    "kano_bus_shelter_long_a": ["aro_canopy_bus_bay_solar_a"], "aro_streetlight_arm_single_a": ["aro_streetlight_single_arm_a"], "aro_streetlight_double_median_a": ["aro_streetlight_double_arm_median_a"],
    "aro_gantry_sign_a": ["aro_gantry_truss_a", "aro_sign_panel_overhead_green_a"], "aro_road_sign_direction_a": ["aro_sign_km_marker_a"], "aro_guardrail_post_set": ["aro_guardrail_wbeam_a"],
    "aro_jersey_barrier_a": ["aro_median_barrier_jersey_a"], "aro_kerb_painted_run_a": ["aro_kerb_painted_blackwhite_a", "aro_kerb_painted_yellowblack_a"], "aro_drain_grate_set": ["aro_drain_grating_strip_a"],
    "aro_litter_bin_a": ["aro_bin_a"], "aro_planter_island_a": ["aro_planter_island_kerbed_a", "aro_median_planter_kerbed_a"], "aro_planter_island_b": ["aro_planter_island_kerbed_a", "aro_median_planter_kerbed_a"],
    "kano_utility_pole_set": ["aro_pole_electric_concrete_span_a", "rg_ngn_pole_timber_span_a"], "aro_truck_trailer_parked_a": ["aro_trailer_box_a"],
    "rg_ngn_mosque_medium_a": ["kano_neighbourhood_mosque_a"], "rg_ngn_mosque_medium_b": ["kano_neighbourhood_mosque_a"], "rg_ngn_mosque_medium_c": ["kano_neighbourhood_mosque_a"],
    "rg_ngn_mosque_small_a": ["kano_neighbourhood_mosque_a"], "rg_ngn_mosque_small_b": ["kano_neighbourhood_mosque_a"], "rg_ngn_mosque_small_c": ["kano_neighbourhood_mosque_a"],
    "aro_flyover_deck_segment_a": ["aro_flyover_deck_pier_a"], "aro_flyover_pier_a": ["aro_flyover_deck_pier_a"], "aro_flyover_pier_b": ["aro_flyover_deck_pier_a"],
}
SAME_ID = {"aro_bench_a", "aro_pallet_stack_a"}                  # the registry already has an entry with this id: it moves to this version


def library_of(aid: str, x: dict) -> str:
    if x["family"] == "F": return "modern_architecture"
    if x["family"] == "E": return "traditional_architecture"                                  # the registry's own category for the (planned, blocked) neighbourhood and great mosques
    if x["family"] == "D":
        if aid == "lmk_kano_roundabout_monument_a": return "modern_architecture"
        if aid in ("rg_ngn_island_wall_a", "rg_ngn_pattern_panel_a", "rg_ngn_pattern_panel_b", "rg_ngn_pattern_panel_c"): return "boundaries_walls_gates"
        return "site_props_vehicles" if aid == "aro_roundabout_fountain_a" else "road_structure_signs_lighting"
    if aid in ("rg_ngn_warehouse_hall_a", "rg_ngn_warehouse_hall_b", "rg_ngn_warehouse_cold_a", "aro_dock_leveller_set", "kano_bus_terminal_hall_a"): return "modern_architecture"
    if aid in ("aro_gate_sliding_a", "aro_fence_palisade_set", "aro_wall_plot_set"): return "boundaries_walls_gates"
    if aid == "aro_fuel_island_truck": return "markets_roadside_businesses"
    if aid == "aro_drain_grate_set": return "drainage_flooding"
    if x["family"] == "C" and aid not in ("aro_bench_a", "aro_litter_bin_a", "aro_planter_island_a", "aro_planter_island_b"): return "road_structure_signs_lighting"
    if aid == "aro_yard_mast_light": return "road_structure_signs_lighting"
    return "site_props_vehicles"


def name_of(sp: dict) -> str:
    n = sp["note"].split(";")[0].strip(); return n[:1].upper() + n[1:]


def sha(p: Path) -> str:
    h = hashlib.sha256(); h.update(p.read_bytes()); return h.hexdigest()


def put(src: Path, dst: Path, log: list):
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists():
        if dst.read_bytes() != src.read_bytes(): raise SystemExit(f"REFUSED: {dst} exists with different bytes (append-only library)")
        return
    shutil.copy2(src, dst); log.append(str(dst))


def freeze(C: Path, ids, version="v001") -> dict:
    """SHA-256 of every file this release stages (a text file: the game repository keeps it as docs/kano/TRANSPORT_KIT.freeze.json)."""
    out = {}
    for aid in sorted(ids):
        d = C / "unity" / "Models" / aid / version
        for f in sorted(d.iterdir()): out[f"unity/Models/{aid}/{version}/{f.name}"] = {"sha256": sha(f), "bytes": f.stat().st_size}
    return out


def main() -> int:
    ap = argparse.ArgumentParser(); ap.add_argument("--content", required=True); ap.add_argument("--game-docs", required=True); ap.add_argument("--previews", default=""); ap.add_argument("--commit", default=""); ap.add_argument("--family", default="", help="only the assets of this family (A, B, C, D or E); a batch staged later")
    a = ap.parse_args()
    from PIL import Image
    from .build_transport import SPECS, load_all
    from . import common as C_, scenes as SC
    load_all(); C = Path(a.content).resolve(); G = Path(a.game_docs).resolve(); W = ws.default_root(); added: list = []
    reg_path = C / "registry" / "asset_registry.json"; reg = json.loads(reg_path.read_text()); by_id = {x["id"]: x for x in reg["assets"]}; lic = (C / "LICENSES.md").read_text()
    cat = json.loads((G / "TRANSPORT_KIT_catalog.json").read_text()); scenes = {s.name: s for s in SC.all_scenes()}; rows = []; staged = []
    tex_have = {p.name: p for p in (C / "unity" / "Textures").rglob("T_*.png")}
    for aid, sp in SPECS.items():
        x = C_.EXTRAS[aid]
        if a.family and x["family"] != a.family: continue
        kind = sp["kind"]; v = sorted(p.name for p in (W / "exports" / "fbx" / aid).iterdir() if p.is_dir())[-1]; n = int(v[1:])
        if v != "v001": raise SystemExit(f"{aid}: expected v001, the workspace has {v}")
        proj = W / "projects" / kind / aid / v; val = W / "validation" / aid / f"{v}.json"; stats = json.loads(val.read_text())["stats"]; entry = next(e for e in cat["props"] if e["id"] == aid)
        if (C / "unity" / "Models" / aid / v).exists(): raise SystemExit(f"REFUSED: {aid} {v} is already in the library")
        for f in proj.iterdir():
            if f.is_file() and f.suffix.lower() != ".png": put(f, C / "blender" / "projects" / kind / aid / v / f.name, added)
        put(val, C / "blender" / "validation" / aid / f"{v}.json", added); u = C / "unity" / "Models" / aid / v; files = []
        for fmt in ("fbx", "glb"):
            src = W / "exports" / fmt / aid / v / f"{aid}.{fmt}"; put(src, u / src.name, added); files.append({"path": src.name, "sha256": sha(u / src.name), "bytes": (u / src.name).stat().st_size})
        man_src = W / "exports" / "fbx" / aid / v / f"{aid}.manifest.json"; put(man_src, C / "blender" / "export_manifests" / aid / v / f"{aid}.manifest.json", added)
        for f in proj.glob("T_*.png"):
            if f.name in tex_have:
                if tex_have[f.name].read_bytes() != f.read_bytes(): raise SystemExit(f"REFUSED: texture {f.name} exists in the library with other bytes")
            else: put(f, C / "unity" / "Textures" / "transport_kit" / f.name, added); tex_have[f.name] = C / "unity" / "Textures" / "transport_kit" / f.name
        refs = [r for r in x["ref"] if r.startswith("R-")]; concepts = refs
        manifest = {"id": aid, "version": n, "kind": kind, "files": files, "source": {"blend": f"blender/projects/{kind}/{aid}/{v}/{aid}.blend", "script": "tools/blender/transport_kit (Online-African-Road, branch claude/intelligent-faraday-sykb0x)", "toolchain": "aro-blender on Blender 5.2.3 LTS"},
                    "madeBy": {"human": "the owner (direction, the approved breakdown of 2026-11-09 and the references " + ", ".join(refs) + "); modelling code written by Claude", "tools": TOOLS},
                    "licence": {"kind": "owner-owned", "evidence": LICENCE_EVIDENCE.format(refs=", ".join(refs)), "thirdParty": THIRD_PARTY}, "references": refs, "budgets": {"lodTriangles": stats["lod_triangles"]},
                    "catalogEntry": entry, "sockets": x.get("sockets", []), "approval": None}
        (u / f"{aid}.manifest.json").write_text(json.dumps(manifest, indent=2)); added.append(str(u / f"{aid}.manifest.json"))
        rows.append(f"| {aid} | {n} | Claude (code), owner (direction) | {', '.join(refs)} | original geometry and procedural textures; design references {', '.join(refs)} (generated concepts, not Kano-verified); ownership confirmed by the owner 2026-11-01 (third-party tools listed in the registry) | pending, 2026-11-09 |")
        pv = []
        if a.previews:
            for k in ("iso", "front"):
                src = Path(a.previews) / f"{aid}_{k}.png"
                if src.is_file(): d = C / "previews" / aid / v; d.mkdir(parents=True, exist_ok=True); Image.open(src).convert("RGB").save(d / f"{aid}_{k}.jpg", "JPEG", quality=88, optimize=True); pv.append(f"previews/{aid}/{v}/{aid}_{k}.jpg")
        placements = [{"scene": f"env_{s.name}_dry", "district": {"A": "D10", "B": "D09", "C": "-", "D": "-", "E": "-", "F": "-"}[x["family"]], "count": sum(1 for i in s.items if i["asset"] == aid)} for s in scenes.values() if any(i["asset"] == aid for i in s.items)]
        cols = sp["cols"]; collision = {"type": "box", "size": [round(cols[0][3] - cols[0][0], 3), round(cols[0][4] - cols[0][1], 3), round(cols[0][5] - cols[0][2], 3)], "boxes": len(cols)} if cols else {"type": "none"}
        flag = ("OPEN: design interpretation of the generated concept reference(s) " + ", ".join(refs) + " (not Kano-verified; first-pass colours and proportions); no brand, plate or logo; not imported into Unity, not reviewed, not approved"
                + ("; **overlaps the library plan**: the registry also lists " + ", ".join(OVERLAP[aid]) + " for the same thing (the owner decides which id the game uses)" if aid in OVERLAP else "") + ("; built on the owner's instruction that family D follows E5; the family D rows of the breakdown were not individually approved; fictional design interpretation where the id says monument or pattern" if x["family"] == "D" else "")
                + ("; family E: built on the owner's Kano densification directive of 2026-11-09 (mosque family), a GENERIC mosque design: not the Kano Central Mosque and not any real mosque (owner decision C1: " + ("no real landmark is modelled" if "traditional" not in aid else "traditional forms are a flagged interpretation of documentary sources R-024 to R-029, no licensed photograph") + "); it does not replace the planned `kano_neighbourhood_mosque_a` / `lmk_kano_great_mosque`" if x["family"] == "E" else "")
                + ("; family F: built on the owner's Kano densification directive of 2026-11-09 (city fabric of the R-039 skyline), a GENERIC design with blank sign bands (no brand, no billboard text)" + ("; the monument is a FICTIONAL designed civic monument, no real Kano monument is claimed" if "monument" in aid else "") if x["family"] == "F" else "") + "; " + sp["note"])
        new = {"id": aid, "name": name_of(sp), "assetClass": x["class"], "category": entry["category"], "region": "ngn" if aid.startswith("rg_ngn_") else None, "city": "kano" if aid.startswith(("kano_", "lmk_kano_")) else None, "approvedCities": [],
               "concepts": concepts, "districts": {"A": ["D10"], "B": ["D09"], "C": [], "D": [], "E": [], "F": []}[x["family"]], "status": "blender_validation_passed", "breakdownApproved": x["family"] not in ("D", "E", "F"),
               "blenderSource": manifest["source"]["blend"], "export": f"unity/Models/{aid}/{v}/{aid}.fbx", "unityPrefab": None, "placements": placements,
               "validation": {"blender": f"blender/validation/{aid}/{v}.json", "unityImport": None, "visualReview": None}, "approvedBy": None,
               "plannedBudget": {"lod0TrisMax": stats["budget_triangles"], "note": "validator ceiling for the category; the approved breakdown row (docs/KANO_TRANSPORT_ASSET_BREAKDOWN.md) gives the expected count"},
               "engineDependencies": [], "flags": flag, "library": library_of(aid, x), "dimensions": stats["size_m"], "lodTriangles": stats["lod_triangles"], "collision": collision,
               "lods": [{"level": i, "triangles": t} for i, t in enumerate(stats["lod_triangles"])], "materials": stats["materials"], "textures": sorted(f.stem for f in proj.glob("T_*.png")),
               "licence": manifest["licence"], "unity": {"imported": False, "compiled": False, "inGameVerified": False, "prefab": None, "note": f"{v} is not imported into Unity yet (the review workflow is wired, not run); the in-game visual review is for the owner and has NOT happened; not approved"},
               "previews": pv}
        if aid in OVERLAP: new["overlapsPlanned"] = OVERLAP[aid]
        if x.get("sockets"): new["sockets"] = x["sockets"]
        if aid in SAME_ID:
            old = by_id[aid]; new["concepts"] = sorted(set(old.get("concepts", [])) | set(concepts)); new["districts"] = sorted(set(old.get("districts", [])) | set(new["districts"])); new["name"] = old.get("name", new["name"])
            new["flags"] = (old.get("flags") or "").split(" | OPEN: ")[0] + (" | " if old.get("flags") else "") + new["flags"]
            reg["assets"][reg["assets"].index(old)] = {**old, **new}
        else:
            if aid in by_id: raise SystemExit(f"REFUSED: {aid} is already in the registry")
            reg["assets"].append(new)
        staged.append((aid, v, stats["lod_triangles"]))
    mk = C / "unity" / "Materials" / "aro_materials.json"; libm = json.loads(mk.read_text()); newm = json.loads((W / "exports" / "unity" / "aro_materials.json").read_text()); have = {m["name"]: m for m in libm["materials"]}; add = []
    for m in newm["materials"]:
        if m["name"] in have:
            if have[m["name"]] != m: raise SystemExit(f"REFUSED: material {m['name']} differs from the library's definition")
        else: add.append(m)
    libm["materials"] = sorted(libm["materials"] + add, key=lambda m: m["name"]); mk.write_text(json.dumps(libm, indent=1)); print("materials added:", len(add))
    (C / "LICENSES.md").write_text(lic.rstrip("\n") + "\n" + "\n".join(rows) + "\n"); reg_path.write_text(json.dumps(reg, indent=1, ensure_ascii=False) + "\n")
    for s in scenes.values(): j = s.as_json(); (C / "unity" / "placements").mkdir(parents=True, exist_ok=True); (C / "unity" / "placements" / f"{j['scene']}.json").write_text(json.dumps(j, indent=1)); added.append(f"unity/placements/{j['scene']}.json")
    fr = freeze(C, [i for i, _, _ in staged]); (C / "manifests").mkdir(exist_ok=True)
    (C / "manifests" / ("transport_kit" + (("_family_" + a.family.lower()) if a.family else "") + ".freeze.json")).write_text(json.dumps({"release": "transport_kit_v001", "date": time.strftime("%Y-%m-%d", time.gmtime()), "producingCommit": a.commit, "files": fr}, indent=1))
    rel = {"release": "transport_kit" + (("_family_" + a.family.lower()) if a.family else ""), "date": time.strftime("%Y-%m-%d", time.gmtime()), "assets": [{"id": i, "version": v, "lodTriangles": t} for i, v, t in staged], "status": "blender_validation_passed (see registry); not imported into Unity until a review run says so",
           "note": "Families A (logistics), B (bus terminals) and C (road furniture) of the owner's decision of 2026-11-09, as built by tools/blender/transport_kit. Nothing is reviewed or approved. 24 of the 52 overlap an asset the library plan lists under another id (registry field overlapsPlanned)."}
    (C / "manifests" / ("transport_kit" + (("_family_" + a.family.lower()) if a.family else "") + ".release.json")).write_text(json.dumps(rel, indent=2))
    ref_src = G / "REFERENCE_REGISTER.md"
    if ref_src.is_file(): shutil.copy2(ref_src, C / "references" / "REFERENCE_REGISTER.md")
    print(f"staged {len(staged)} assets; {len(added)} files added; {len(fr)} files in the freeze manifest"); return 0


if __name__ == "__main__":
    sys.exit(main())
